import networkx as nx
G = nx.Graph()
for i in range(23):
    for j in range(i+1, 23):
        if len(list(G.neighbors(i))) < 7 and len(list(G.neighbors(j))) < 7:
            G.add_edge(i, j)
            if len(list(G.neighbors(i))) == 3 or len(list(G.neighbors(j))) == 3:
                break
print(G.edges())
